svg.script:
(function () {
  var root = document.documentElement;
  var chips = Array.prototype.slice.call(document.querySelectorAll('.chip'));
  var edges = Array.prototype.slice.call(document.querySelectorAll('.edge'));
  var current = null;
  function show(s) {
    current = (current === s) ? null : s;
    root.classList.toggle('focus', current !== null);
    chips.forEach(function (c) { c.classList.toggle('on', c.getAttribute('data-s') === current); });
    edges.forEach(function (e) {
      var st = (e.getAttribute('data-s') || '').split(' ');
      e.classList.toggle('hi', current !== null && st.indexOf(current) !== -1);
    });
  }
  chips.forEach(function (c) {
    c.addEventListener('click', function (ev) { ev.stopPropagation(); show(c.getAttribute('data-s')); });
    c.addEventListener('keydown', function (ev) {
      if (ev.key === 'Enter' || ev.key === ' ') { ev.preventDefault(); show(c.getAttribute('data-s')); }
    });
  });
  root.addEventListener('click', function () { if (current !== null) show(current); });
})();
